<script setup lang="ts">import {ref,onMounted} from 'vue';import {api} from '../../api';import {t} from '../../locales';import '../../styles/app.scss';const profile=ref<any>({});const username=ref('');const email=ref('');const head=ref('');const wallet=ref('');const emailCode=ref('');const loading=ref(false);onMounted(async()=>{try{profile.value=await api.profile();username.value=profile.value.username||profile.value.nickname||'';email.value=profile.value.email||'';head.value=profile.value.head||profile.value.avatar||'';wallet.value=profile.value.walletAddress||profile.value.wallet||''}catch(error:any){uni.showToast({title:error?.message||t('资料加载失败'),icon:'none'})}});async function save(){if(!username.value.trim()||!email.value.trim())return uni.showToast({title:t('请输入昵称和邮箱'),icon:'none'});loading.value=true;try{await api.updatePersonalInfo({username:username.value.trim(),email:email.value.trim(),head:head.value.trim(),walletAddress:wallet.value.trim(),emailCode:emailCode.value.trim()});profile.value=await api.profile();uni.showToast({title:t('资料已更新'),icon:'none'})}catch(error:any){uni.showToast({title:error?.message||t('资料更新失败'),icon:'none'})}finally{loading.value=false}}async function bindWallet(){if(!wallet.value.trim())return uni.showToast({title:t('请输入钱包地址'),icon:'none'});try{await api.bindWallet(wallet.value.trim());uni.showToast({title:t('钱包绑定成功'),icon:'none'})}catch(error:any){uni.showToast({title:error?.message||t('钱包绑定失败'),icon:'none'})}}</script>
<template><view class="inner-page"><view class="inner-nav"><text class="back" @click="uni.navigateBack()">‹</text><text class="nav-title">{{t('个人资料')}}</text></view><view class="inner-main"><view class="inner-card profile-card"><view class="profile-avatar">♙</view><view class="form-field"><text class="form-label">{{t('昵称')}}</text><input v-model="username" class="form-input" :placeholder="t('输入昵称')"/></view><view class="form-field"><text class="form-label">{{t('邮箱')}}</text><input v-model="email" class="form-input" :placeholder="t('输入邮箱')"/></view><view class="form-field"><text class="form-label">{{t('邮箱验证码')}}</text><input v-model="emailCode" class="form-input" :placeholder="t('修改邮箱时填写')"/></view><view class="form-field"><text class="form-label">{{t('头像地址')}}</text><input v-model="head" class="form-input" :placeholder="t('输入头像 URL')"/></view><view class="form-field"><text class="form-label">{{t('钱包地址')}}</text><input v-model="wallet" class="form-input" :placeholder="t('输入钱包地址')"/><button class="action-button wallet-action" @click="bindWallet">{{t('绑定钱包')}}</button></view><button class="action-button" :disabled="loading" @click="save">{{loading?t('保存中...'):t('保存资料')}}</button></view></view></view></template><style scoped>.profile-card{margin-top:4rpx}.profile-avatar{display:grid;place-items:center;width:78rpx;height:78rpx;margin:0 auto 26rpx;border-radius:50%;background:var(--cf-brand);color:#fff;font-size:40rpx}.wallet-action{margin-top:14rpx}.action-button[disabled]{opacity:.6}</style>
